def transform(grid):
    """Repair isolated one-cell noise by copying the surrounding object's color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            for rr, cc in q:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(q)

    # Only singleton components are speckles; choose the modal color in their
    # immediate 8-neighborhood, leaving the input unchanged while voting.
    for comp in components:
        if len(comp) != 1:
            continue
        r, c = comp[0]
        votes = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (dr or dc) and 0 <= nr < h and 0 <= nc < w:
                    votes.append(grid[nr][nc])
        if votes:
            counts = Counter(votes)
            best = max(counts.values())
            # Ties are resolved by proximity to the speckle (cardinal first),
            # then by stable numeric order.
            tied = {color for color, n in counts.items() if n == best}
            near = [grid[r + dr][c + dc] for dr, dc in ((-1, 0), (0, -1), (0, 1), (1, 0))
                    if 0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] in tied]
            out[r][c] = near[0] if near else min(tied)
    return out
